<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigRetryDelayAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigRetryDelayAccessor trait.
 *
 * Covers null default, string/VO assignment via withRetryDelay,
 * getRetryDelay/retryDelay accessors, and isRetryDelayChanged with/without original.
 */
class SmtpOutboundConfigRetryDelayAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRetryDelay creates a new instance with the RetryDelay set
     * from a string value, and getRetryDelay returns the primitive string.
     */
    public function testWithRetryDelayFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigRetryDelayAccessorUnitTest();

        // Act
        $result = $holder->withRetryDelay(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getRetryDelay());
    }
    /**
     * Asserts that withretryDelay has access to the value object
     * from a string value, and getRetryDelay returns the primitive string.
     */
    public function testWithRetryDelayFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigRetryDelayAccessorUnitTest();

        // Act
        $result = $holder->withRetryDelay(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->retryDelay()->value());
    }
    public function testChangedRetryDelay(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigRetryDelayAccessorUnitTest()->withRetryDelay(1);
        $original = $holder->withRetryDelay( 1);
        $same = $holder->withRetryDelay( 1);
        $modified = $holder->withRetryDelay(2);

        // Act
        $withSame = $original->isRetryDelayChanged( $same );
        $withDiferent = $original->isRetryDelayChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigRetryDelayAccessorUnitTest
{
  use SmtpOutboundConfigRetryDelayAccessor;
}
